def _assert_aura_buffs_subtype(name, subtype, task, helper_name):
    """Generic aura test: opening ``name`` and ``helper_name`` (which carries
    ``subtype``) should add at least one to the friendly ``task`` total.

    Compares ``_staff_total`` with and without ``name`` on the battlefield.
    """
    # Helper-only baseline.
    game, p1, _p2 = _setup()
    helper = _open_active(game, p1, helper_name)
    baseline, _ = scp._staff_total(game.state, p1.id, [helper.id], task)

    # With aura source.
    game2, q1, _q2 = _setup()
    helper2 = _open_active(game2, q1, helper_name)
    source = _open_active(game2, q1, name)
    boosted, _ = scp._staff_total(game2.state, q1.id, [helper2.id], task)

    assert boosted > baseline, (
        f"{name} aura should buff {helper_name} ({subtype}) {task} "
        f"(baseline={baseline}, boosted={boosted})"
    )


