def test_on_assign_sleep_deprived_intern_first_is_free():
    """Sleep-Deprived Intern's first assignment per turn does NOT exhaust."""
    game, p1, _p2 = _setup()
    anomaly = _open_active(game, p1, "Moth in the Camera")
    _strip_reveal_state(anomaly)
    intern = _open_active(game, p1, "Sleep-Deprived Intern")

    ok, _msg, _events = scp.run_test(game, p1.id, anomaly.id, [intern.id])
    assert ok
    # Per scp_assigns_this_turn==1 branch in personnel_quirks.py, intern is
    # un-exhausted after the engine first marks them exhausted.
    assert intern.state.scp_exhausted is False, (
        "Sleep-Deprived Intern should not be exhausted after first assignment"
    )


def test_on_assign_janitor_who_knows_too_much_hushes_breach():
    """Janitor on suppression: breach -1."""
    game, p1, _p2 = _setup()
    anomaly = _open_active(game, p1, "The Concrete Saint")
    _strip_reveal_state(anomaly)
    janitor = _open_active(game, p1, "Janitor Who Knows Too Much")

    # Seed breach so the -1 is visible.
    scp.site(game.state, p1.id)["breach"] = 3
    before = _snap_site(game, p1.id)
    scp.suppress_anomaly(game, p1.id, anomaly.id, [janitor.id])
    after = _snap_site(game, p1.id)
    assert after["breach"] == before["breach"] - 1, (
        f"Janitor on suppress should drop breach by 1: {before['breach']} -> {after['breach']}"
    )


