def test_on_reveal_recursive_hallway():
    """Recursive Hallway: tax own pending dossiers. Need 2 pending cards."""
    game, p1, _p2 = _setup()
    # Open a pending Keter Annex first so the tax has a target.
    scp.site(game.state, p1.id)["clearance"] = 3
    pending = _hand_card(game, p1, "Keter Annex")
    assert scp.open_dossier(game, p1.id, pending.id)[0]  # not fast_track -> stays pending
    paperwork_before = pending.state.scp_paperwork
    # Now open Recursive Hallway fast_track -> reveal fires -> taxes pending.
    _open_active(game, p1, "Recursive Hallway")
    paperwork_after = pending.state.scp_paperwork
    assert paperwork_after > paperwork_before, (
        f"Recursive Hallway reveal should add paperwork ({paperwork_before} -> {paperwork_after})"
    )


