def _stack_research_staff(game, p1, anomaly_curiosity):
    """Open enough research staff to beat the given curiosity. Returns the
    list of staff ids. Site clearance is raised to accommodate O5/Deepwell.
    """
    scp.site(game.state, p1.id)["clearance"] = 6
    staff_ids = []
    # Big-hitters first for headroom.
    for name in ("O5 Auditor", "Night Shift Archivist", "Memetics Analyst", "Junior Researcher"):
        s = _open_active(game, p1, name)
        staff_ids.append(s.id)
    # Add bonus facility to be extra safe.
    _open_active(game, p1, "Deepwell Archive")
    return staff_ids


def test_on_test_recursive_hallway_success_breach_cleanup():
    """Recursive Hallway: on success, breach -1 (self_cleanup)."""
    game, p1, _p2 = _setup()
    anomaly = _open_active(game, p1, "Recursive Hallway")
    _strip_reveal_state(anomaly, game)
    staff = _stack_research_staff(game, p1, anomaly.scp_curiosity if hasattr(anomaly, 'scp_curiosity') else 3)
    # Seed breach so the -1 is observable.
    scp.site(game.state, p1.id)["breach"] = 3
    before = _snap_site(game, p1.id)
    ok, msg, events = scp.run_test(game, p1.id, anomaly.id, staff)
    assert ok, msg
    after = _snap_site(game, p1.id)
    # Engine emitted SCP_TEST_RUN with success=True, then on_test hook fires.
    success_events = [e for e in events if e.type == EventType.SCP_TEST_RUN]
    assert success_events and success_events[0].payload["success"], (
        f"Recursive Hallway test must succeed for on_test to fire (events={[e.type.name for e in events]})"
    )
    assert after["breach"] < before["breach"], (
        f"Recursive Hallway on_test self_cleanup should drop breach (delta={_site_delta(before, after)})"
    )


