def test_on_test_red_room_static_cognitive_load():
    """Red Room Static: success grants secrecy+1 AND exhausts an extra researcher."""
    game, p1, _p2 = _setup()
    # _cognitive_load is now a PendingChoice; AI registration resolves it
    # inline via heuristic_pick (lowest-research researcher).
    game.turn_manager.set_ai_player(p1.id)
    anomaly = _open_active(game, p1, "Red Room Static")
    _strip_reveal_state(anomaly, game)
    staff = _stack_research_staff(game, p1, 4)
    # Open one extra fresh researcher to act as the cognitive_load victim.
    _open_active(game, p1, "D-Class Volunteer")
    # Capture how many active personnel are non-exhausted before the test.
    pre_active = sum(
        1
        for pid in game.state.scp_personnel[p1.id]
        if not game.state.objects[pid].state.scp_exhausted
    )
    ok, _msg, _events = scp.run_test(game, p1.id, anomaly.id, staff)
    assert ok
    post_active = sum(
        1
        for pid in game.state.scp_personnel[p1.id]
        if not game.state.objects[pid].state.scp_exhausted
    )
    # We exhausted the assigned staff (len(staff)) AND one extra via cognitive_load.
    expected_drop = len(staff) + 1
    actual_drop = pre_active - post_active
    assert actual_drop >= expected_drop, (
        f"Red Room Static cognitive_load should exhaust 1 extra researcher "
        f"(pre={pre_active}, post={post_active}, assigned={len(staff)}, drop={actual_drop})"
    )


