def test_on_test_fail_recursive_hallway_breach_punish():
    """Recursive Hallway fail: breach +1 (on top of engine's hazard leak)."""
    game, p1, _p2 = _setup()
    anomaly = _open_active(game, p1, "Recursive Hallway")
    _strip_reveal_state(anomaly, game)
    before = _snap_site(game, p1.id)
    ok, _msg, events = scp.run_test(game, p1.id, anomaly.id, [])
    assert ok
    after = _snap_site(game, p1.id)
    # Failure: engine adds max(1, hazard - total). hazard=1, total=0 -> +1 from
    # engine + the breach_punish hook's +1 = +2 minimum.
    assert after["breach"] - before["breach"] >= 2, (
        f"Recursive Hallway fail should bump breach by >=2 "
        f"(delta={_site_delta(before, after)}, engine_leak + breach_punish)"
    )
    # Verify the engine ran the fail branch.
    fail_events = [e for e in events if e.type == EventType.SCP_TEST_RUN]
    assert fail_events and not fail_events[0].payload["success"]


