def _contain_for_aura_test(game, player, name):
    """Open + force-contain an anomaly so its contained_bonus applies."""
    anomaly = _open_active(game, player, name, clearance_boost=2)
    anomaly.state.scp_status = "contained"
    if anomaly.id in game.state.scp_anomalies[player.id]:
        game.state.scp_anomalies[player.id].remove(anomaly.id)
    if anomaly.id not in game.state.scp_contained[player.id]:
        game.state.scp_contained[player.id].append(anomaly.id)
    return anomaly


def _assert_contained_bonus(name, task, expected_min):
    """Force-contain ``name`` and verify _active_bonus reports task >= expected."""
    game, p1, _p2 = _setup()
    _contain_for_aura_test(game, p1, name)
    actual = scp._active_bonus(game.state, p1.id, task)
    assert actual >= expected_min, (
        f"{name} contained_bonus should report {task} >= {expected_min} (got {actual})"
    )


