# ---------------------------------------------------------------------------
# CORE PROCEDURES -- scp_effect (22 cards)
# ---------------------------------------------------------------------------
# Each procedure is opened fast_track; the effect fires immediately at
# _activate_dossier, then the card moves to the graveyard.


def _assert_procedure_effect(name, *, clearance_boost: int = 0, expected_zone: ZoneType = ZoneType.GRAVEYARD, predicate=None):
    """Open ``name`` fast_track, assert it lands in expected_zone (default: graveyard)
    and that ``predicate(game, p1, before, after)`` holds.

    ``predicate`` receives the game, player, and site dicts before/after open.
    """
    game, p1, _p2 = _setup()
    if clearance_boost:
        scp.site(game.state, p1.id)["clearance"] += clearance_boost
    before = _snap_site(game, p1.id)
    obj = _hand_card(game, p1, name)
    ok, msg, _events = scp.open_dossier(game, p1.id, obj.id, fast_track=True)
    assert ok, f"{name} open failed: {msg}"
    after = _snap_site(game, p1.id)
    assert obj.zone == expected_zone, (
        f"{name} should move to {expected_zone.name}, got {obj.zone}"
    )
    if predicate:
        predicate(game, p1, before, after)


