# ---------------------------------------------------------------------------
# Test runner
# ---------------------------------------------------------------------------


def _summarize(passed, failed, errors):
    """Print formatted results table to stdout."""
    total = len(passed) + len(failed) + len(errors)
    skipped = len(SKIPPED_CARDS)
    print()
    print("=" * 60)
    print("  SCP CORE Interceptor Verification")
    print("=" * 60)
    print(f"  passed:    {len(passed)}")
    print(f"  failed:    {len(failed)}")
    print(f"  errors:    {len(errors)}")
    print(f"  skipped:   {skipped} (see SKIPPED_CARDS dict)")
    if total:
        print(f"  pass rate: {100 * len(passed) / total:.1f}%")
    if failed:
        print("\n  --- FAILURES ---")
        for name, msg in failed[:50]:
            print(f"    {name}: {msg[:160]}")
    if errors:
        print("\n  --- ERRORS ---")
        for name, msg in errors[:50]:
            print(f"    {name}: {msg[:160]}")


if __name__ == "__main__":
    tests = sorted(
        [(k, v) for k, v in globals().items() if k.startswith("test_") and callable(v)],
        key=lambda kv: kv[0],
    )
    passed, failed, errors = [], [], []
    for name, fn in tests:
        try:
            fn()
            passed.append(name)
        except AssertionError as e:
            failed.append((name, str(e) or "AssertionError"))
        except Exception as e:
            errors.append((name, f"{type(e).__name__}: {e}"))
    _summarize(passed, failed, errors)
    sys.exit(0 if not failed and not errors else 1)
